+#[derive(Parser)]
+struct Argument {
+    #[arg(long, default_value = "4096")]
+    width: NonZeroUsize,
+    #[arg(long, default_value = "32")]
+    length: NonZeroUsize,
+    #[arg(long, default_value = "21")]
