+use super::{Entry, Set};
+use crate::state::Token;
+
+pub(crate) enum Traversal<'set> {
+    Complete(Entry<'set>),
+    Shared(Cursor<'set>),
+}
+
+impl<'set> Traversal<'set> {
+    pub(super) fn new(source: &'set Set, target: Option<&'set Set>) -> Self {
+        let Some(target) = target.filter(|target| source.shared(target)) else {
+            return Self::Complete(source.entry());
+        };
+        Self::Shared(Cursor {
+            source,
+            target,
+            position: 0,
+            word: 0,
+        })
+    }
+}
+
+impl<'set> Iterator for Traversal<'set> {
+    type Item = (usize, &'set Token);
+
+    fn next(&mut self) -> Option<Self::Item> {
+        match self {
+            Self::Complete(entry) => entry.next(),
+            Self::Shared(cursor) => cursor.next(),
+        }
+    }
+}
+
+impl std::iter::FusedIterator for Traversal<'_> {}
+
+pub(crate) struct Cursor<'set> {
+    source: &'set Set,
+    target: &'set Set,
+    position: usize,
+    word: u64,
+}
+
+impl<'set> Iterator for Cursor<'set> {
+    type Item = (usize, &'set Token);
+
+    fn next(&mut self) -> Option<Self::Item> {
+        let width = self.source.value.as_ref().map_or(0, |value| value.len());
+        while self.word == 0 {
+            if self.position >= width.div_ceil(64) {
+                return None;
+            }
+            let selected = |value: &Set| {
+                value
+                    .selection
+                    .as_ref()
+                    .map_or(u64::MAX, |value| value.word[self.position])
+            };
+            self.word = selected(self.source) & !selected(self.target);
+            self.word &= u64::MAX >> (64 - (width - self.position * 64).min(64));
+            self.position += 1;
+        }
+        let position = (self.position - 1) * 64 + self.word.trailing_zeros() as usize;
+        self.word &= self.word - 1;
+        Some((position, self.source.at(position)))
+    }
+}
