+use crate::change::Change;
+use crate::state::{State, Token};
+
+fn difference<'state>(
+    current: &'state State,
+    previous: &'state State,
+    frame: &'state [usize],
+) -> impl Iterator<Item = &'state Token> {
+    frame
+        .iter()
+        .filter_map(|&position| current.frame.get(position).map(|frame| (position, frame)))
+        .flat_map(|(position, frame)| {
+            let previous = previous.frame.get(position).map(|frame| &frame.particle);
+            frame
+                .held
+                .iter()
+                .chain(frame.particle.removed(previous).map(|(_, token)| token))
+        })
+}
+
+pub(super) fn advance(previous: usize, source: &State, state: &State, change: &Change) -> usize {
+    let newest = state
+        .world
+        .range(change.insertion.clone())
+        .flat_map(|world| &world.particle)
+        .chain(difference(state, source, &change.frame))
+        .map(|token| token.id)
+        .max()
+        .map_or(0, |identity| identity + 1);
+    if newest >= previous {
+        return newest;
+    }
+    let retired = change
+        .world
+        .iter()
+        .flat_map(|&world| &source.world[world].particle)
+        .chain(difference(source, state, &change.frame))
+        .any(|token| token.id + 1 == previous);
+    if retired {
+        return new(state);
+    }
+    previous
+}
+
+pub(super) fn new(state: &State) -> usize {
+    state
+        .world
+        .iter()
+        .flat_map(|world| &world.particle)
+        .chain(state.frame.iter().flat_map(|frame| frame.token()))
+        .map(|token| token.id)
+        .max()
+        .map_or(0, |identity| identity + 1)
+}
