+fn multiplicity() {
+    let mut state = state(3);
+    let largest = usize::MAX - 1;
+    let frame = Arc::make_mut(&mut state.frame[0]);
+    frame.particle.push(token(largest));
+    frame.particle.push(token(largest));
+    frame.held.push(token(largest));
+    Arc::make_mut(&mut state.world[0])
